"""Current documentation tables: explicit workflow scope, no numerical adoption."""
from pathlib import Path
import pandas as pd

def add_workflow_tables(views, out):
    rows=[
      ('W01','Source reconciliation','Implemented source layer','All registered contributor/provider inputs','../sbc-donham-kelp-mpa-data','make sources; make trace; make check','Source measurements, corrections, exclusions and mass traces','Required inputs validated; does not certify biomass support or downstream fits','docs/ANALYSIS_GUIDE.md'),
      ('W02','Inherited biomass production','Existing implementation; not newly endorsed','Existing program/response cohorts','../sbc-donham-kelp-mpa-data','make harmonize','output/review/raw_sources','Comparison/role/year/species pools can cross stations, dates, zones and programs; historical reconstruction; current integrated estimates come from W08','../sbc-donham-kelp-mpa-data/docs/RAW_TO_BIOMASS.md'),
      ('W03','PISCO joint borrowed-size review','Review only','Six animal histories at Abalone Cove and Point Vicente','.','python3 code/tools/run_joint_biomass_review.py','outputs/joint_borrowed_biomass_20261102','Restricted matching and shared-donor uncertainty do not replace inherited production automatically','outputs/joint_borrowed_biomass_20261102/README.md'),
      ('W04','KFM sheephead biomass','Review only; 52 comparison-years','Four existing fish comparisons; fully supported visits','.','python3 code/tools/run_kfm_sheephead_biomass_review.py','outputs/kfm_sheephead_biomass_20261103','Same-site sizes within seven days; no cross-site/year borrowing; not before-after or total uncertainty','outputs/kfm_sheephead_biomass_20261103/README.md'),
      ('W05','KFM matched-visit alternative','Candidate coverage only; not fitted','55 potential comparison-years with unchanged annual site membership','.','python3 code/tools/audit_kfm_missing_size_recovery.py; python3 code/tools/check_kfm_missing_size_recovery.py','outputs/kfm_missing_size_recovery_20261103','Would drop unmatched count visits and renormalize weights; not recovered annual observations','outputs/kfm_missing_size_recovery_20261103/README.md'),
      ('W06','LTER release reconciliation','Source comparison only','Adult kelp through 2023; updated provider aggregate compared separately','.','python3 code/tools/reconcile_lter_annual_biomass.py; python3 code/tools/decompose_lter_reconciliation.py','outputs/fish_lter_reconciliation_20261102','Keep adult monthly conversion; provider adult-plus-juvenile aggregate is not interchangeable','outputs/fish_lter_reconciliation_20261102/README.md'),
      ('W07','Documentation and inventory','Current decision view; no model fitting','All linked audit scopes','.','python3 code/tools/report_dataset_inventory.py; python3 code/tools/check_current_decisions.py; python3 code/tools/check_documentation_consolidation.py','outputs/dataset_inventory_20261101','Refreshing tables does not run analysis or freeze the primary cohort','docs/ANALYSIS_GUIDE.md')]
    workflow=pd.DataFrame(rows,columns=['workflow_id','workflow','status','scope','working_directory_relative_to_analysis_repo','commands','outputs','adoption_limit','evidence'])
    workflow['input_record'] = [
        '../sbc-donham-kelp-mpa-data/config/source_manifest.json',
        '../sbc-donham-kelp-mpa-data/config/source_manifest.json',
        'outputs/joint_borrowed_biomass_20261102/README.md',
        'outputs/kfm_sheephead_biomass_20261103/inputs.json',
        'outputs/kfm_missing_size_recovery_20261103/input_manifest.json',
        'outputs/fish_lter_reconciliation_20261102/input_manifest.json',
        'outputs/dataset_inventory_20261101/README.md']
    workflow['prerequisites'] = ['Private registered inputs and existing Python/R environments', 'Source build, existing R environment and contributor inputs', 'Prepared review inputs and existing Python scientific environment', 'Scott fish export in the private data-repository review archive, current count roster and Python scientific environment', 'Scott export, original legacy archive, current review ledgers and original Drive copies', 'Pinned review sources and mounted NAS containing older SBC50.20 release', 'Existing audit outputs; does not rebuild their analyses']
    gates=pd.DataFrame([
      ('G01','Source identity','File/release and original row','Resolve physical identifiers; validate units, sentinel values and hashes','Hold unresolved required records; preserve originals','No automatic exclusion of other years or responses'),
      ('G02','Ecological scope','Program/physical site/response','Apply researcher advice and ecological restrictions before calculations and donor calibration','Record exact reason and evidence; keep excluded rows in ledger','Do not transfer benthic exclusions indiscriminately to fish'),
      ('G03','Survey comparability','Station/visit/method/depth/zone','Check common zones, survey method, effort and repeated visits','Show what is lost under each coverage rule; unresolved habitat stays explicit','No universal inter-role date-gap or fixed-station policy is adopted'),
      ('G04','Response support','Count and size measurement separately','Counts can support density while sizes fail biomass support','Positive count with unsupported size yields unknown biomass; explicit unknown is never zero','KFM review also requires size support at zero-count visits to quantify uncertainty'),
      ('G05','Aggregation','Retained visits and stations in both roles','Multiply density and mean mass within matched visits, then apply declared weights','Do not silently omit an unsupported station or visit and renormalize','The 55-year KFM option would change visits and therefore remains separate'),
      ('G06','Model eligibility','Comparison/time series','Use calendar years actually observed; separate before-after from post-protection trends','Record why a model is unsupported without erasing valid observations','Do not choose inclusion or model rules from effect direction/significance'),
      ('G07','Release','Complete analysis build','Compare corrected outputs, diagnostics, tables and paper claims','Keep review outputs separate until reviewed and adopted','Source checks passing is not primary-analysis approval')],columns=['gate_id','decision','unit','rule','if_not_met','scope_limit'])
    biomass=pd.DataFrame([
      ('M01','Measured fish or invertebrate sizes','Convert each length/diameter to mass using taxon-specific units; average mass with frequency weights','mean_mass_g = sum(frequency * mass_g) / sum(frequency)','Within the documented size pool','Keep source row and frequency; a row can represent several fish'),
      ('M02','Count plus separate sizes','Pair within survey visit before annual averaging','biomass_g_m2 = count_per_m2 * mean_mass_g','Integrated KFM urchin/kelp: same site/year, nearest <=7 days; exact-date sensitivity. PISCO: approved local or calibrated matching. KFM sheephead: separate restricted review.','Reused size survey receives shared uncertainty; count density and size sample are different surveys'),
      ('M03','LTER group-mean diameter','Convert the recorded group mean, preserving count and group identity','proxy_mean_mass_g = a * recorded_mean_diameter_mm ** b','Recorded survey group','Not the mean of individual masses; within-group variance cannot be recovered'),
      ('M04','LTER lobster missing lengths','Use documented same-site/date mean individual mass','imputed_mass_g = mean(donor_individual_mass_g)','Five audited records only','Preserve missing length and donor links; no new observed length is created'),
      ('M05','Kelp','Use recorded survey-month Model1 coefficient for adult stipes','dry_foliar_mass_g = stipes * monthly_slope_kg_per_stipe * 1000','Adult diver kelp response','Per-plant KFM measurements still require plant density; satellite wet canopy and provider adult+juvenile aggregate differ'),
      ('M06','Unknown or zero','Keep observation state separate from point estimate and uncertainty','observed_zero -> point_zero; unknown -> NA','Verified surveyed units only','Zero observations do not prove ecological absence or zero sampling variance')],columns=['method_id','input','calculation','formula','scope','limitation'])
    for label,filename,frame in [('Workflow status','workflow_status.csv',workflow),('Inclusion gates','inclusion_gates.csv',gates),('Biomass calculations','biomass_calculations.csv',biomass)]:
        frame.to_csv(out/filename,index=False);views[label]=frame.fillna('')
    return views
